    """Extend each 3x3 ring with center 2 along the intervening 2-guide lattice."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ring = [(0,0),(0,1),(0,2),(1,0),(1,2),(2,0),(2,1),(2,2)]
    centers=[]
