        for c in range(w-2):
            if grid[r+1][c+1]==2 and all(grid[r+dr][c+dc]==3 for dr,dc in ring):
                centers.append((r+1,c+1))
    # From each ring, trace its center row and column outward through gaps.
    # At each crossed 2-guide, keep the 2 center but color the adjacent guide cells.
    for mr,mc in centers:
        for dc in (-1,1):
            cc=mc+dc
            while 0<=cc<w:
                if grid[mr][cc]==0: out[mr][cc]=1
                elif grid[mr][cc]==2:
                    # continue through 2 rails, retaining their central pixels
                    pass
