    # adjacent cells, forming the cross-shaped junction seen in the demos.
    for mr,mc in centers:
        for rr in range(h):
            if grid[rr][mc]==2:
                for cc in (mc-1,mc+1):
                    if 0<=cc<w and grid[rr][cc]==2: out[rr][cc]=1
