from pathlib import Path
Path('programs/task-fb36bf09.py').write_text('''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ring = [(0,0),(0,1),(0,2),(1,0),(1,2),(2,0),(2,1),(2,2)]
    centers = []
    for r in range(h-2):
        for c in range(w-2):
            if grid[r+1][c+1] == 2 and all(grid[r+dr][c+dc] == 3 for dr,dc in ring):
                centers.append((r+1,c+1))
    if not centers:
        return out
    # The repeated 2 rails determine the projection axis.
    row_strength = max((sum(v == 2 for v in row) for row in grid), default=0)
    col_strength = max((sum(grid[r][c] == 2 for r in range(h)) for c in range(w)), default=0)
    if col_strength >= row_strength:
        # Vertical rails: extend each motif across its entire center row.
        for mr, mc in centers:
            for cc in range(w):
                if grid[mr][cc] == 0:
                    out[mr][cc] = 1
            # At each crossed guide, draw a one-cell cross around its 2.
            for cc in range(w):
                if grid[mr][cc] == 2:
                    for rr, c2 in ((mr-1,cc),(mr+1,cc),(mr,cc-1),(mr,cc+1)):
                        if 0 <= rr < h and 0 <= c2 < w and grid[rr][c2] in (0,2):
                            out[rr][c2] = 1
    else:
        # Horizontal rails: project vertically from each motif toward the
        # nearest other horizontal 2 rail, then continue beyond that rail.
        rails = [r for r,row in enumerate(grid) if sum(v == 2 for v in row) >= w-1]
        for mr, mc in centers:
            targets = [r for r in rails if r != mr]
            if not targets:
                continue
            target = min(targets, key=lambda r: abs(r-mr))
            step = 1 if target > mr else -1
            rr = mr + step
            while 0 <= rr < h:
                if grid[rr][mc] == 0:
                    out[rr][mc] = 1
                if grid[rr][mc] == 2:
                    for cc in (mc-1,mc+1):
                        if 0 <= cc < w and grid[rr][cc] in (0,2):
                            out[rr][cc] = 1
                rr += step
    return out
''')
